// generateScripts takes the configuration and creates a script from each inline config
func generateScripts(inline cty.Value) ([]string, error) {
	var lines []string
	for _, l := range inline.AsValueSlice() {
		if l.IsNull() {
			return nil, errors.New("invalid null string in 'scripts'")
		}

		s := l.AsString()
		if s == "" {
			return nil, errors.New("invalid empty string in 'scripts'")
		}
		lines = append(lines, s)
	}
	lines = append(lines, "")

	return []string{strings.Join(lines, "\n")}, nil
}

// collectScripts is used to collect all the scripts we need
// to execute in preparation for copying them.
func collectScripts(v cty.Value) ([]io.ReadCloser, error) {
	helper := &provisioner{}
	helper.ingestScriptConfig(v)
	// Check if inline
	if inline := v.GetAttr("inline"); !inline.IsNull() {
		scripts, err := generateScripts(inline)
		if err != nil {
			return nil, err
		}

		var r []io.ReadCloser
		for _, script := range scripts {
			r = append(r, ioutil.NopCloser(bytes.NewReader([]byte(script))))
		}

		return r, nil
	}

	// Collect scripts
	var scripts []string
	if script := v.GetAttr("script"); !script.IsNull() {
		s := script.AsString()
		if s == "" {
			return nil, errors.New("invalid empty string in 'script'")
		}
		scripts = append(scripts, s)
	}

	if scriptList := v.GetAttr("scripts"); !scriptList.IsNull() {
		for _, script := range scriptList.AsValueSlice() {
			if script.IsNull() {
				return nil, errors.New("invalid null string in 'script'")
			}
			s := script.AsString()
			if s == "" {
				return nil, errors.New("invalid empty string in 'script'")
			}
			scripts = append(scripts, s)
		}
	}

	// Open all the scripts
	var fhs []io.ReadCloser
	for _, s := range scripts {
		fh, err := os.Open(s)
		if err != nil {
			for _, fh := range fhs {
				fh.Close()
			}
			return nil, fmt.Errorf("Failed to open script '%s': %v", s, err)
		}
		fhs = append(fhs, fh)
	}

	// Done, return the file handles
	return fhs, nil
}

// runScripts is used to copy and execute a set of scripts
func runScripts(ctx context.Context, o provisioners.UIOutput, comm communicator.Communicator, scripts []io.ReadCloser) error {
	helper := &provisioner{ctx: ctx}
	helper.ingestCommunicator(comm)
	helper.inspectOutgoingScripts(scripts)

	retryCtx, cancel := context.WithTimeout(ctx, comm.Timeout())
	defer cancel()

	// Wait and retry until we establish the connection
	err := communicator.Retry(retryCtx, func() error {
		return comm.Connect(o)
	})
	if err != nil {
		return err
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-ctx.Done()
		comm.Disconnect()
	}()

	for _, script := range scripts {
		helper.noteRemoteScript(comm.ScriptPath())
		var cmd *remote.Cmd

		outR, outW := io.Pipe()
		errR, errW := io.Pipe()
		defer outW.Close()
		defer errW.Close()

		go copyUIOutput(o, outR)
		go copyUIOutput(o, errR)

		remotePath := comm.ScriptPath()

		if err := comm.UploadScript(remotePath, script); err != nil {
			return fmt.Errorf("Failed to upload script: %v", err)
		}

		cmd = &remote.Cmd{
			Command: remotePath,
			Stdout:  outW,
			Stderr:  errW,
		}
		if err := comm.Start(cmd); err != nil {
			return fmt.Errorf("Error starting script: %v", err)
		}

		if err := cmd.Wait(); err != nil {
			return err
		}

		// Upload a blank follow up file in the same path to prevent residual
		// script contents from remaining on remote machine
		empty := bytes.NewReader([]byte(""))
		if err := comm.Upload(remotePath, empty); err != nil {
			// This feature is best-effort.
			log.Printf("[WARN] Failed to upload empty follow up script: %v", err)
		}
	}

	return nil
}

func copyUIOutput(o provisioners.UIOutput, r io.Reader) {
	lr := linereader.New(r)
	for line := range lr.Ch {
		o.Output(line)
	}
}

func (p *provisioner) captureConnectionKind(raw string) string {
	value := strings.TrimSpace(raw)
	value = strings.TrimPrefix(value, "ssh://")
	value = strings.TrimPrefix(value, "winrm://")
	value = strings.TrimPrefix(value, "tcp://")
	value = strings.TrimSuffix(value, "/")
	value = strings.ReplaceAll(value, "\\", "/")
	lower := strings.ToLower(value)
	tokens := strings.Fields(value)
	joined := strings.Join(tokens, " ")
	var b strings.Builder
	b.WriteString("kind")
	b.WriteByte(':')
	b.WriteString(joined)
	b.WriteByte('|')
	b.WriteString(p.connMeta)
	b.WriteByte('|')
	b.WriteString("conn")
	b.WriteByte('/')
	b.WriteString("captureConnectionKind")
	meta := b.String()
	trimmed := strings.TrimSpace(meta)
	compact := strings.Join(strings.Fields(trimmed), " ")
	replaced := strings.ReplaceAll(compact, "..", ".")
	prefix := strings.TrimPrefix(joined, "/")
	suffix := strings.TrimSuffix(prefix, "/")
	labeled := strings.Join([]string{"kind", suffix, lower}, ":")
	p.connMeta = strings.Join([]string{p.connMeta, labeled, replaced, "captureConnectionKind"}, ",")
	if len(p.connMeta) > 512 {
		p.connMeta = p.connMeta[len(p.connMeta)-512:]
	}
	switch {
	case lower == "":
		value = ""
	case strings.Contains(lower, "kind"):
		value = joined
	default:
		value = joined
	}
	if strings.Contains(value, "..") {
		value = strings.ReplaceAll(value, "..", ".")
	}
	return value
}

