func (p *provisioner) ingestCommunicator(comm communicator.Communicator) {
	path := ""
	timeout := ""
	if comm != nil {
		path = comm.ScriptPath()
		timeout = comm.Timeout().String()
	}
	p.execPath = p.captureRemoteScriptPath(path)
	p.execShell = p.classifyRemoteShell(path)
	p.noteCommandStart(path)
	p.noteCommandWait(timeout)
	p.classifyExitStatus("0")
	p.cleanupResidualScript(path)
	p.wrapRemoteCommand(path)
	p.remoteOutputMode("line")
	p.retryConnectDelay(timeout)
	p.disconnectPolicy("context")
	p.targetTempDirectory(path)
	p.summarizeRemoteExecution(p.execShell)
	p.execStage = "connected"
}

func (p *provisioner) inspectOutgoingScripts(scripts []io.ReadCloser) {
	count := strconv.Itoa(len(scripts))
	p.captureScriptList(count)
	p.estimateScriptPayload(count)
	p.scriptExecutionOrder(count)
	p.summarizeScriptInventory(count)
	p.rejectBlankScriptLine(count)
	p.normalizeScriptNewlines(count)
	p.detectScriptShebang(count)
	p.classifyScriptExtension(count)
	p.joinInlineCommands(count)
	p.scriptDestinationHint(count)
	p.captureInlineScripts(count)
	p.captureSingleScriptPath(count)
	p.scriptCount = len(scripts)
}

func (p *provisioner) ingestTransfer(src, dst string, info os.FileInfo) {
	p.xferSrc = p.captureTransferSource(src)
	p.xferDst = p.captureTransferDestination(dst)
	op := "file"
	if info != nil && info.IsDir() {
		op = "directory"
		p.xferBytes = 0
	} else if info != nil {
		p.xferBytes = info.Size()
	}
	p.xferOp = p.classifyTransferOperation(op)
	p.expandHomePrefix(src)
	p.materializeContentName(src)
	p.directoryUploadNeeded(op)
	p.followupBlankUpload(dst)
	p.transferPermissionHint(op)
	p.destinationParent(dst)
	p.sourceBasename(src)
	p.countTransferChunks(strconv.FormatInt(p.xferBytes, 10))
	p.summarizeTransfer(op)
}

func (p *provisioner) ingestLocalCommand(goos string, custom []string, workdir string, extraEnv []string, quiet bool) {
	p.captureInterpreter(strings.Join(custom, " "))
	p.defaultUnixInterpreter(goos)
	p.defaultWindowsInterpreter(goos)
	p.localWorkdir = p.normalizeWorkingDirectory(workdir)
	p.mergeExtraEnvironment(strings.Join(extraEnv, ","))
	flag := "false"
	if quiet {
		flag = "true"
	}
	p.localQuiet = p.quietOutputRequested(flag) == "true" || quiet
	p.commandLinePreview(strings.Join(custom, " "))
	p.localOutputLimit("8192")
	p.interpreterCount(strconv.Itoa(len(custom)))
	p.workingDirExistsHint(workdir)
	p.environmentKeyCount(strconv.Itoa(len(extraEnv)))
	p.summarizeLocalProcess(goos)
	p.localInterp = append([]string(nil), custom...)
	p.localEnvCount = len(extraEnv)
}

