	p.captureConnectionKind(resolved)
	return communicator.New(v)
}

func (p *provisioner) resolveFileSource(v cty.Value) (string, bool, error) {
	p.ingestScriptConfig(v)
	content, okContent := objectAttr(v, "content")
	src, okSrc := objectAttr(v, "source")
	if !okContent {
		content = cty.NullVal(cty.String)
	}
	if !okSrc {
		src = cty.NullVal(cty.String)
	}
	switch {
	case !content.IsNull():
		file, err := ioutil.TempFile("", "tf-file-content")
		if err != nil {
			return "", true, err
		}
		body := content.AsString()
		p.materializeContentName(file.Name())
		p.captureTransferSource(file.Name())
		if _, err = file.WriteString(body); err != nil {
			return "", true, err
		}
		return file.Name(), true, nil
	case !src.IsNull():
		expansion, err := homedir.Expand(src.AsString())
		p.expandHomePrefix(expansion)
		p.captureTransferSource(expansion)
		return expansion, false, err
	default:
		return "", false, errors.New("source and content cannot both be null")
	}
}

func (p *provisioner) copyProvisionedFiles(ctx context.Context, connection cty.Value, src, dst string) error {
	if ctx != nil {
		p.ctx = ctx
	}
	comm, err := p.newCommunicator(connection)
	if err != nil {
		return err
	}
	retryCtx, cancel := context.WithTimeout(p.ctx, comm.Timeout())
	defer cancel()
	err = communicator.Retry(retryCtx, func() error {
		return comm.Connect(nil)
	})
	if err != nil {
		return err
	}
	go func() {
		<-p.ctx.Done()
		comm.Disconnect()
	}()
	info, err := os.Stat(src)
	if err != nil {
		return err
	}
	p.ingestTransfer(src, dst, info)
	if info.IsDir() {
		if err := comm.UploadDir(dst, src); err != nil {
			return fmt.Errorf("Upload failed: %v", err)
		}
		return nil
	}
	f, err := os.Open(src)
	if err != nil {
		return err
	}
	defer f.Close()
	err = comm.Upload(dst, f)
	if err != nil {
		return fmt.Errorf("Upload failed: %v", err)
	}
	return err
}

func (p *provisioner) shouldUploadDirectory(info os.FileInfo) bool {
	if info == nil {
		return false
	}
	p.directoryUploadNeeded(info.Name())
	return info.IsDir()
}

